// Approval prototype only. Never calls the booking/auth API or writes a database.
const [catalog,proposal]=await Promise.all(['catalog.json','packages.json'].map(file=>fetch(new URL(file,import.meta.url)).then(r=>r.json())));
const root=document.querySelector('#prototype');
const money=n=>new Intl.NumberFormat('vi-VN').format(n)+'₫';
const state={screen:new URLSearchParams(location.search).get('screen')||'home',property:'residence',room:'ocean',plan:'welcome',arrival:'2026-11-14',departure:'2026-11-16',guests:2,addons:[],confirmed:null};
const screens=['home','rooms','detail','checkout','confirmation','request'];
if(!screens.includes(state.screen))state.screen='home';
const room=()=>catalog.rooms.find(r=>r.id===state.room);
const property=()=>catalog.properties.find(p=>p.id===state.property);
const plan=()=>proposal.packages.find(p=>p.id===state.plan);
const nights=()=>Math.max(1,Math.round((Date.parse(state.departure)-Date.parse(state.arrival))/86400000)||1);
const availablePlans=()=>proposal.packages.filter(p=>p.properties.includes(state.property)&&(p.id!=='slow'||state.guests<=2));
const extras=()=>proposal.addons.filter(s=>state.addons.includes(s.id));
const total=()=>nights()*(room().price+plan().nightlySupplement)+extras().reduce((sum,s)=>sum+s.price,0);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function go(screen){state.screen=screen;render();window.scrollTo(0,0);}
const button=(text,to,style='primary')=>'<button class="'+style+'" data-go="'+to+'">'+text+'</button>';
function benefits(p=plan()){return p.benefits.length?p.benefits.map(b=>'<li><strong>'+b.name+'</strong><br><span>'+b.people+' người · '+b.uses+' · đã gồm, +0₫</span><br><small>'+b.schedule+'</small></li>').join(''):'<li>Chỉ gồm lưu trú và tiện nghi phòng. Không kèm bữa ăn hoặc quà tặng.</li>';}
function search(){return '<form class="searchbar" id="search"><label>Cơ sở<select name="property">'+catalog.properties.map(p=>'<option value="'+p.id+'" '+(p.id===state.property?'selected':'')+'>'+p.name+'</option>').join('')+'</select></label><label>Nhận phòng<input name="arrival" type="date" value="'+state.arrival+'" required></label><label>Trả phòng<input name="departure" type="date" value="'+state.departure+'" required></label><label>Khách<select name="guests">'+[1,2,3,4,5,6].map(g=>'<option '+(g===state.guests?'selected':'')+'>'+g+'</option>').join('')+'</select></label><button class="primary">Tìm phòng →</button></form>';}
function image(src,caption,cls=''){return '<figure class="'+cls+'"><img src="'+src+'" alt="Ảnh tham khảo mỹ thuật, không phải ảnh phòng STAYOS"><figcaption>'+caption+'</figcaption></figure>';}
function header(){return '<div class="review-ribbon">BẢN DUYỆT · Ảnh tham khảo và gói đề xuất, không phải trang mở bán</div><header><a class="brand" href="?screen=home">STAYOS<small>STAY YOUR WAY</small></a><nav aria-label="Điều hướng"><button data-go="home">Hai cơ sở</button><button data-go="rooms">Tìm phòng</button><button data-go="confirmation">Đơn mô phỏng</button></nav><a class="review-link" href="./index.html" target="_top">Bộ duyệt ↗</a></header>';}
function home(){return search()+'<section class="hero"><div class="hero-copy"><p class="eyebrow">MỘT KỲ NGHỈ, THEO CÁCH CỦA BẠN</p><h1>Ở thoải mái.<br>Nghỉ thật riêng.</h1><p>Căn hộ có bếp cho những ngày ở lâu.<br>Phòng nghỉ gọn gàng cho chuyến đi ngắn.<br>Hai lựa chọn, cùng sự rõ ràng trước khi đặt.</p>'+button('Tìm căn phòng của bạn →','rooms')+'<p class="quiet">Vũng Tàu · địa bàn dự kiến, chờ xác nhận địa chỉ.</p></div>'+image('living-reference.jpg','Tham khảo phong cách nội thất · chờ duyệt, không phải ảnh cơ sở','hero-image')+'</section><section class="section"><div class="section-title"><div><p class="eyebrow">CHỌN NƠI PHÙ HỢP</p><h2>Hai cách để ở lại.</h2></div><p>Phòng thuộc một cơ sở cụ thể.<br>Không phải 15 địa điểm riêng biệt.</p></div><div class="property-grid"><article class="property-tile"><span class="number">01</span><h3>STAYOS Residence</h3><p>Khách sạn căn hộ · 8 phòng</p><p>Bếp nhỏ, không gian sinh hoạt và lựa chọn 1–2 phòng ngủ. Phù hợp gia đình và kỳ ở dài.</p><div class="tile-bottom"><strong>Từ 850.000₫ <small>/ đêm</small></strong><button data-property="residence">Xem căn hộ →</button></div></article><article class="property-tile"><span class="number">02</span><h3>STAYOS Inn</h3><p>Nhà nghỉ · 7 phòng</p><p>Phòng đôi, ba, bốn hoặc gia đình. Phòng tắm riêng và tiện nghi thiết yếu cho chuyến đi ngắn.</p><div class="tile-bottom"><strong>Từ 450.000₫ <small>/ đêm</small></strong><button data-property="inn">Xem phòng nghỉ →</button></div></article></div></section>';}
function roomList(){
  const filtered=catalog.rooms.filter(r=>r.propertyId===state.property&&r.capacity>=state.guests);
  const types=[...new Set(filtered.map(r=>r.typeId))];
  return search()+'<section class="section"><p class="crumb">Hai cơ sở / '+property().name+'</p><div class="section-title"><div><p class="eyebrow">'+property().kind+' · '+filtered.length+' PHÒNG PHÙ HỢP</p><h1>Chọn phòng, không phải đoán.</h1></div><p>'+state.arrival+' → '+state.departure+'<br>'+nights()+' đêm · '+state.guests+' khách · kết quả minh họa</p></div><div class="filter-line"><span class="pill">✓ Phòng tắm riêng</span><span class="pill">'+(state.property==='residence'?'Bếp & khu sinh hoạt':'Wi-Fi & điều hòa')+'</span><small>Nhóm theo loại phòng; xem mã phòng cụ thể trước khi đặt.</small></div><div class="room-list">'+types.map((type,i)=>{
    const group=filtered.filter(r=>r.typeId===type),r=group[0],p=plan();
    return '<article class="room-card">'+(i===0?image('bedroom-reference.jpg','Ảnh moodboard · chưa duyệt cho loại phòng này'):'<div class="type-cover"><span>STAYOS / '+property().name.split(' ').at(-1)+'</span><strong>'+r.typeName+'</strong><p>'+r.area+' m² · '+r.beds+'</p><small>Cần bộ ảnh đúng loại phòng — chưa thay bằng ảnh khác.</small></div>')+'<div class="room-copy"><p class="eyebrow">'+group.length+' PHÒNG CÙNG LOẠI · TỪ TẦNG '+r.floor+'</p><h2>'+r.typeName+'</h2><p>'+r.area+' m² · '+r.bedrooms+' phòng ngủ · tối đa '+r.capacity+' khách</p><p>'+r.features.join(' · ')+'</p><label>Mã phòng<select data-unit="'+type+'">'+group.map(u=>'<option value="'+u.id+'">'+u.number+' · tầng '+u.floor+' · '+money(u.price)+'/đêm</option>').join('')+'</select></label><div class="benefit-line">Gói '+p.name+' · '+(p.benefits[0]?.name||'không kèm quà tặng')+'<small>Đề xuất chờ duyệt · không cộng quà lần nữa</small></div></div><div class="room-price"><span>Giá phòng / đêm</span><strong>'+money(r.price)+'</strong><p>Chưa tính nâng gói hoặc dịch vụ mua thêm.</p><button class="primary" data-room="'+r.id+'" data-type="'+type+'">Chi tiết & chọn gói →</button><small>Không thanh toán trong bản duyệt.</small></div></article>';
  }).join('')+(!types.length?'<p>Không có phòng đủ sức chứa. Hãy đổi số khách hoặc cơ sở.</p>':'')+'</div></section>';
}
function planCards(){return '<div class="plans">'+availablePlans().map(p=>'<label class="plan-card '+(state.plan===p.id?'selected':'')+'"><input type="radio" name="plan" value="'+p.id+'" '+(state.plan===p.id?'checked':'')+'><span><strong>'+p.name+'</strong><small>'+money(room().price+p.nightlySupplement)+' / đêm</small><ul>'+benefits(p)+'</ul><em>Đề xuất · cần duyệt '+p.decision.split(':')[0]+'</em></span></label>').join('')+'</div>';}
function policy(){return '<div class="policy"><h3>Biết rõ trước khi đặt</h3><dl><div><dt>Nhận / trả phòng</dt><dd>14:00 / 12:00 · giờ Việt Nam</dd></div><div><dt>Thuế / phí / cọc</dt><dd>Giá demo gồm thuế; vệ sinh 0₫, cọc 0₫. Chính sách thật chờ duyệt.</dd></div><div><dt>Hủy đơn demo</dt><dd>Miễn phí đến hết ngày đến nếu chưa nhận phòng. Điều kiện mở bán cần chủ cơ sở xác nhận.</dd></div><div><dt>Vị trí & liên hệ</dt><dd>Chưa xác nhận địa chỉ, chỗ đỗ xe, hướng nhìn hoặc số hỗ trợ. Không cung cấp chỉ đường giả.</dd></div></dl></div>';}
function detail(){const r=room();return '<section class="section"><button class="back" data-go="rooms">← Các phòng tại '+property().name+'</button><div class="section-title"><div><p class="eyebrow">'+property().name+' · TẦNG '+r.floor+'</p><h1>'+r.name+'</h1><p>'+r.area+' m² · '+r.beds+' · tối đa '+r.capacity+' khách</p></div><span class="pill">Danh tính phòng được giữ đến khi đặt</span></div><div class="gallery">'+image('bedroom-reference.jpg','01 / Phòng ngủ — tham khảo phong cách, không phải phòng '+r.number)+image('living-reference.jpg','02 / Khu sinh hoạt — moodboard chờ duyệt')+'<div class="gallery-brief"><span>03 / PHÒNG TẮM</span><strong>Ảnh cần bổ sung</strong><p>Đúng loại phòng, thấy khu tắm và lavabo. Không thay bằng ảnh phòng ngủ.</p></div><div class="gallery-brief view"><span>04 / HƯỚNG NHÌN</span><strong>Chưa xác minh view</strong><p>Chụp từ cửa sổ phòng '+r.number+'. Không hứa view biển hoặc ban công.</p></div></div><p class="quiet">Hai ảnh trên chỉ để duyệt cách bố trí gallery. Không khẳng định cùng một căn phòng; chưa được phép dùng làm bộ ảnh mở bán.</p><div class="detail-columns"><div><h2>Không gian dành cho bạn</h2><p>'+r.subtitle+'. '+(r.propertyId==='residence'?'Phù hợp người muốn tự chuẩn bị bữa ăn và có chỗ sinh hoạt riêng.':'Phù hợp khách cần một chỗ nghỉ riêng, gọn gàng sau một ngày ra ngoài.')+'</p><div class="amenities">'+r.features.map(f=>'<span>✓ '+f+'</span>').join('')+'</div><h2>Chọn điều đã bao gồm</h2><p>Tiện nghi phòng luôn có trong giá. Quyền lợi gói bên dưới là đề xuất đang chờ duyệt.</p>'+planCards()+policy()+'</div><aside class="quote-card"><p>'+r.number+' / '+property().name+'</p><h2>'+money(r.price+plan().nightlySupplement)+' <small>/ đêm</small></h2><p>'+state.arrival+' → '+state.departure+'<br>'+nights()+' đêm · '+state.guests+' khách</p><div class="benefit-line">Gói '+plan().name+'<ul>'+benefits()+'</ul></div><div class="sum-line"><span>Tạm tính gói lưu trú</span><strong>'+money((r.price+plan().nightlySupplement)*nights())+'</strong></div>'+button('Tiếp tục đặt phòng →','checkout')+'<small>Chỉ mô phỏng. Không giữ phòng hay thu tiền.</small></aside></div></section>';}
function summary(){return '<aside class="quote-card"><p class="eyebrow">KỲ NGHỈ ĐÃ CHỌN</p><h2>'+room().name+'</h2><p>'+property().name+' · '+room().area+' m²<br>'+room().beds+' · '+state.guests+' khách</p><p>'+state.arrival+' → '+state.departure+' · '+nights()+' đêm</p><div class="sum-line"><span>Phòng · '+nights()+' × '+money(room().price)+'</span><strong>'+money(nights()*room().price)+'</strong></div><div class="sum-line"><span>Nâng gói '+plan().name+'</span><strong>'+money(nights()*plan().nightlySupplement)+'</strong></div><ul class="included-list">'+benefits()+'</ul>'+extras().map(s=>'<div class="sum-line"><span>'+s.name+'<small>'+s.unit+'</small></span><strong>'+money(s.price)+'</strong></div>').join('')+'<div class="sum-line"><span>Vệ sinh / cọc</span><strong>0₫ / 0₫</strong></div><div class="sum-total"><span>Tổng minh họa</span><strong>'+money(total())+'</strong></div><p class="quiet">Giá demo đã gồm thuế. Quyền lợi trong gói không bị tính tiền thêm. Chưa thu tiền.</p></aside>';}
function checkout(){return '<section class="section"><button class="back" data-go="detail">← Chi tiết & gói phòng</button><p class="eyebrow">01 CHỌN PHÒNG → 02 CHỌN GÓI → <b>03 KIỂM TRA</b></p><h1>Rõ ràng trước khi xác nhận.</h1><div class="checkout-columns"><div><section class="white-panel"><h2>1. Gói '+plan().name+'</h2><ul>'+benefits()+'</ul><button class="text-link" data-go="detail">Đổi gói lưu trú</button></section><section class="white-panel"><h2>2. Thêm nếu bạn cần</h2><p>Không bắt buộc · từng đơn vị tính được ghi riêng · tất cả chờ duyệt nhà cung cấp.</p>'+proposal.addons.filter(s=>s.properties.includes(state.property)).map(s=>'<label class="addon-row"><input type="checkbox" data-addon="'+s.id+'" '+(state.addons.includes(s.id)?'checked':'')+'><span><strong>'+s.name+'</strong><small>'+s.description+'</small><small>'+s.conditions+'</small></span><b>'+money(s.price)+'<small>'+s.unit+'</small></b></label>').join('')+'</section><section class="white-panel"><h2>3. Thông tin liên hệ</h2><p>Đề xuất: cho xem báo giá trước; giữ lựa chọn khi đăng nhập. Form này chỉ là mẫu, không gửi dữ liệu.</p><div class="contact-fields"><label>Họ tên<input value="Khách xem bản duyệt" readonly></label><label>Email<input value="khach@example.test" readonly></label></div><button class="text-link" id="simulate-login">Mô phỏng đăng nhập & giữ lựa chọn</button><p id="login-result" role="status"></p></section>'+policy()+'<p class="approval-note">Mọi gói và quyền lợi ở đây chưa được đưa vào hệ thống booking thật.</p><button class="primary wide" id="confirm-preview">Xác nhận mô phỏng · '+money(total())+'</button><small class="quiet">Không gọi API, không tạo đơn thật, không gửi email.</small></div>'+summary()+'</div></section>';}
function confirmation(){if(!state.confirmed)return '<section class="section empty"><h1>Chưa có đơn mô phỏng.</h1><p>Bắt đầu từ tìm phòng để kiểm tra toàn bộ luồng, không cần đăng nhập thật.</p>'+button('Bắt đầu tìm phòng →','rooms')+'</section>';
  const draft={...state};
  Object.assign(state,state.confirmed.selection);
  try{return confirmationSnapshot();}finally{Object.assign(state,draft);}
}
function confirmationSnapshot(){
  return '<section class="section"><p class="eyebrow">HOÀN THÀNH LUỒNG XEM DUYỆT</p><h1>Đã lưu bản mô phỏng.</h1><p>Mã PREVIEW-001 · chỉ nằm trong bộ nhớ tab, không phải đơn đặt phòng.</p><div class="status-track"><span class="active">① Đã lưu bản mô phỏng</span><span>② Chờ thanh toán — chưa tích hợp</span><span>③ Xác nhận lưu trú — chưa phát hành</span></div><div class="checkout-columns"><div class="white-panel"><h2>Quyền lợi nhân viên cần phục vụ</h2><p>'+room().number+' · Gói '+plan().name+'</p><ul>'+benefits()+'</ul><h3>Dịch vụ mua thêm</h3>'+(extras().length?'<ul>'+extras().map(s=>'<li>'+s.name+' · '+s.unit+' · '+money(s.price)+' · lịch chờ thống nhất</li>').join('')+'</ul>':'<p>Không chọn dịch vụ mua thêm.</p>')+'<h3>Gửi xác nhận cho khách</h3><p>Đề xuất email gồm mã phòng, gói, lịch, quyền lợi và tổng tiền. Chưa cấu hình gửi email; màn hình này không báo “đã gửi”.</p>'+button('Chọn yêu cầu gửi nhân viên →','request')+'</div>'+summary()+'</div></section>';}
function request(){return '<section class="section narrow"><p class="eyebrow">YÊU CẦU HỖ TRỢ · THIẾT KẾ ĐỀ XUẤT</p><h1>Bạn cần hỗ trợ gì?</h1><p>Biểu mẫu có lựa chọn rõ ràng. Không gọi là AI hay concierge tự động.</p><form id="support" class="white-panel"><label>Loại yêu cầu<select><option>Hẹn giờ sử dụng quyền lợi</option><option>Hỏi giờ nhận phòng</option><option>Yêu cầu dọn phòng</option><option>Vấn đề khác</option></select></label><label>Nội dung<textarea required placeholder="Ví dụ: muốn dùng bữa sáng lúc 08:00…"></textarea></label><button class="primary">Gửi mô phỏng</button><p role="status" id="support-result">Chỉ minh họa; chưa có hàng đợi nhân viên.</p></form></section>';}
function render(){
  root.innerHTML=header()+({home,rooms:roomList,detail,checkout,confirmation,request}[state.screen])()+'<footer><strong>STAYOS</strong><p>Thiết kế xem duyệt · hai cơ sở mô phỏng · không phải thông tin mở bán.</p><a href="./index.html" target="_top">Bảng giá, quyền lợi và điểm cần duyệt ↗</a></footer>';
  root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
  root.querySelectorAll('[data-property]').forEach(b=>b.onclick=()=>{state.property=b.dataset.property;state.room=catalog.rooms.find(r=>r.propertyId===state.property).id;state.plan='welcome';state.addons=[];go('rooms');});
  root.querySelector('#search')?.addEventListener('submit',e=>{
    e.preventDefault();const f=new FormData(e.target),a=f.get('arrival'),d=f.get('departure');
    if(d<=a){e.target.querySelector('[name=departure]').setCustomValidity('Ngày trả phải sau ngày nhận.');e.target.reportValidity();return;}
    state.property=f.get('property');state.arrival=a;state.departure=d;state.guests=Number(f.get('guests'));state.addons=[];
    if(!availablePlans().some(p=>p.id===state.plan))state.plan='welcome';
    state.room=(catalog.rooms.find(r=>r.propertyId===state.property&&r.capacity>=state.guests)||catalog.rooms.find(r=>r.propertyId===state.property)).id;go('rooms');
  });
  root.querySelector('[name=departure]')?.addEventListener('input',e=>e.target.setCustomValidity(''));
  root.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{state.room=root.querySelector('[data-unit="'+b.dataset.type+'"]').value;go('detail');});
  root.querySelectorAll('[data-unit]').forEach(select=>select.onchange=()=>{
    const unit=catalog.rooms.find(r=>r.id===select.value);
    select.closest('.room-card').querySelector('.room-price>strong').textContent=money(unit.price);
  });
  root.querySelectorAll('[name=plan]').forEach(el=>el.onchange=()=>{state.plan=el.value;render();});
  root.querySelectorAll('[data-addon]').forEach(el=>el.onchange=()=>{state.addons=el.checked?[...state.addons,el.dataset.addon]:state.addons.filter(id=>id!==el.dataset.addon);render();});
  root.querySelector('#simulate-login')?.addEventListener('click',()=>{root.querySelector('#login-result').textContent='Mô phỏng đăng nhập thành công. Giữ '+room().number+', '+plan().name+', '+nights()+' đêm và tổng '+money(total())+'. Không gửi thông tin tài khoản.';});
  root.querySelector('#confirm-preview')?.addEventListener('click',()=>{
    const {screen,confirmed,...selection}=state;
    state.confirmed={selection:structuredClone(selection),total:total()};
    go('confirmation');
  });
  root.querySelector('#support')?.addEventListener('submit',e=>{e.preventDefault();root.querySelector('#support-result').textContent='Đã mô phỏng ghi nhận yêu cầu. Chưa gửi cho nhân viên.';});
}
render();
